; sprites.asm -- chapter 20: three loops in lines with four sprites
; generated by gen20.py
        INCLUDE "msx.inc"
        OUTPUT "sprites.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
        INCLUDE "bios.inc"
IM2_TABLE EQU $C200             ; 257 bytes of $C3: every vector is $C3C3
IM2_JUMP  EQU $C3C3             ; and there, a JP to the routine
BOX_EMPTY EQU 1             ; the library's two boxes, characters 1 and 2
BOX_FULL  EQU 2
; 96 bytes of text written with three of speeds.asm's loops, one a frame,
; each started in the paper's line 130, at the same T-state as there; four
; sprites, black squares, are drawn in each line from 128 to 191.
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off while the page is drawn
        VDP_REG 0, $00          ; Graphic I: 32 x 24 characters
        VDP_REG 2, $06          ; names              $1800
        VDP_REG 3, $80          ; colours            $2000
        VDP_REG 4, $00          ; patterns           $0000
        VDP_REG 5, $36          ; sprite attributes  $1B00
        VDP_REG 6, $07          ; sprite patterns    $3800
        VDP_REG 7, $0F          ; border white
        VRAM_WRITE $0000        ; the BIOS character set: 256 x 8 bytes
        ld hl, (CGTABL)
        ld bc, 2048
.font:  ld a, (hl)
        out (VDP_DATA), a
        inc hl
        dec bc
        ld a, b
        or c
        jr nz, .font
        VRAM_WRITE $0008        ; characters 1 and 2: the bit boxes
        ld hl, boxes
        ld b, 16
.box:   ld a, (hl)
        out (VDP_DATA), a
        inc hl
        djnz .box
        VRAM_WRITE $2000        ; colours: black ink (1) on white paper (15)
        ld b, 32
        ld a, $1F
.col:   out (VDP_DATA), a
        djnz .col
        VRAM_WRITE $1800        ; names: all spaces
        ld bc, 768
.clr:   ld a, ' '
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, .clr
        VRAM_WRITE $1B00        ; no sprites
        ld a, $D0
        out (VDP_DATA), a
        ld b, 0
        ld c, 0
        ld hl, l23
        call puts
        ld b, 4
        ld c, 0
        ld hl, l25
        call puts
        ld b, 8
        ld c, 0
        ld hl, l26
        call puts
        VRAM_WRITE $3800        ; sprite pattern 0: a filled square
        ld a, $FF
        ld b, 8
sq:     out (VDP_DATA), a
        djnz sq
        VRAM_WRITE $1B00        ; 32 sprites: Y, X, pattern 0, colour 1 (black)
        ld hl, sprite_table
        ld b, 128
        ld c, VDP_DATA
        otir
        ld hl, IM2_TABLE        ; mode 2: the table, 257 bytes of $C3
        ld de, IM2_TABLE + 1
        ld bc, 256
        ld (hl), high IM2_JUMP
        ldir
        ld a, $C3               ; and at $C3C3, JP isr
        ld (IM2_JUMP), a
        ld hl, isr
        ld (IM2_JUMP + 1), hl
        ld a, high IM2_TABLE
        ld i, a                 ; I: the page of the table
        im 2
        VDP_REG 1, $E0          ; display on, and the frame's signal on
        in a, (VDP_CTRL)        ; no signal left over from before
        ei
        halt                    ; the frame's interrupt
        di
        ld a, ($002B)           ; 14: bit 7 is 1 on a 50 Hz machine
        rla                     ;  5
        jp nc, f23j         ; 11
f235s:  ld de, 1901
f235:   dec de
        ld a, d
        or e
        jr nz, f235
        ld c, 0
        nop
        nop
        nop
        nop
        jp f23g             ; 11
f23j:
f236s:  ld de, 1514
f236:   dec de
        ld a, d
        or e
        jr nz, f236
        ld c, 0
        ld c, 0
        nop
f23g:
s23:
        ld hl, text             ; 11
        ld c, VDP_DATA          ;  8
        VRAM_WRITE $1820        ; 40
        ld b, 96
        otir                    ; 23 a byte, 18 the last
z23:
        in a, (VDP_CTRL)        ; no signal left over from before
        ei
        halt                    ; the frame's interrupt
        di
        ld a, ($002B)           ; 14: bit 7 is 1 on a 50 Hz machine
        rla                     ;  5
        jp nc, f25j         ; 11
f255s:  ld de, 1901
f255:   dec de
        ld a, d
        or e
        jr nz, f255
        ld c, 0
        nop
        nop
        nop
        nop
        jp f25g             ; 11
f25j:
f256s:  ld de, 1514
f256:   dec de
        ld a, d
        or e
        jr nz, f256
        ld c, 0
        ld c, 0
        nop
f25g:
s25:
        ld hl, text             ; 11
        ld c, VDP_DATA          ;  8
        VRAM_WRITE $18A0        ; 40
        DUP 96
        ld a, (hl)              ;  8
        inc l                   ;  5
        out (VDP_DATA), a       ; 12: 25
        EDUP
z25:
        in a, (VDP_CTRL)        ; no signal left over from before
        ei
        halt                    ; the frame's interrupt
        di
        ld a, ($002B)           ; 14: bit 7 is 1 on a 50 Hz machine
        rla                     ;  5
        jp nc, f26j         ; 11
f265s:  ld de, 1901
f265:   dec de
        ld a, d
        or e
        jr nz, f265
        ld c, 0
        nop
        nop
        nop
        nop
        jp f26g             ; 11
f26j:
f266s:  ld de, 1514
f266:   dec de
        ld a, d
        or e
        jr nz, f266
        ld c, 0
        ld c, 0
        nop
f26g:
s26:
        ld hl, text             ; 11
        ld c, VDP_DATA          ;  8
        VRAM_WRITE $1920        ; 40
        DUP 96
        outi                    ; 18
        ld a, (hl)              ;  8: 26, and A is not used
        EDUP
z26:
done:   jr done

; isr: the frame's interrupt, taken once, to start in step with the picture
isr:    push af
        in a, (VDP_CTRL)        ; the status: the VDP takes its signal down
        pop af
        ei
        ret
l23:        db "OTIR: 23 T A BYTE", 0
l25:        db "LD A,(HL)/INC L/OUT: 25 T", 0
l26:        db "OUTI/LD A,(HL), UNROLLED: 26 T", 0
sprite_table:  ; a sprite is drawn from line Y + 1
        db 127, 32, 0, 1
        db 127, 96, 0, 1
        db 127, 160, 0, 1
        db 127, 224, 0, 1
        db 135, 32, 0, 1
        db 135, 96, 0, 1
        db 135, 160, 0, 1
        db 135, 224, 0, 1
        db 143, 32, 0, 1
        db 143, 96, 0, 1
        db 143, 160, 0, 1
        db 143, 224, 0, 1
        db 151, 32, 0, 1
        db 151, 96, 0, 1
        db 151, 160, 0, 1
        db 151, 224, 0, 1
        db 159, 32, 0, 1
        db 159, 96, 0, 1
        db 159, 160, 0, 1
        db 159, 224, 0, 1
        db 167, 32, 0, 1
        db 167, 96, 0, 1
        db 167, 160, 0, 1
        db 167, 224, 0, 1
        db 175, 32, 0, 1
        db 175, 96, 0, 1
        db 175, 160, 0, 1
        db 175, 224, 0, 1
        db 183, 32, 0, 1
        db 183, 96, 0, 1
        db 183, 160, 0, 1
        db 183, 224, 0, 1
        ALIGN 256
text:   db "ABCDEFGHIJKLMNOPQRSTUVWXYZ012345ABCDEFGHIJKLMNOPQRSTUVWXYZ012345ABCDEFGHIJKLMNOPQRSTUVWXYZ012345"

; at: B = row (0-23), C = column (0-31) -> the VDP's write address is that
;     cell of the name table. Keeps BC, DE. Uses A, HL.
at:     push de
        ld l, b
        ld h, 0
        add hl, hl
        add hl, hl
        add hl, hl
        add hl, hl
        add hl, hl              ; row x 32
        ld e, c
        ld d, $18
        add hl, de              ; + $1800 + column
        ld a, l
        out (VDP_CTRL), a
        ld a, h
        or $40
        out (VDP_CTRL), a
        pop de
        ret

; putc: A = character, B = row, C = column. Keeps BC, DE, HL.
putc:   push hl
        push af
        call at
        pop af
        out (VDP_DATA), a
        pop hl
        ret

; puts: HL = text ending in 0, B = row, C = column; C moves on.
puts:   ld a, (hl)
        or a
        ret z
        call putc
        inc hl
        inc c
        jr puts

; puthex: A = a byte, as two hexadecimal digits; C moves on by 2.
puthex: push af
        rrca
        rrca
        rrca
        rrca                    ; the high four bits first
        call hexdig
        pop af
hexdig: and %00001111
        add a, '0'
        cp '9' + 1
        jr c, .digit
        add a, 'A' - '9' - 1    ; 10-15 become A-F
.digit: call putc
        inc c
        ret
boxes:                          ; characters 1 (empty box) and 2 (filled)
        db %11111110, %10000010, %10000010, %10000010, %10000010, %10000010, %11111110, %00000000
        db %11111110, %11111110, %11111110, %11111110, %11111110, %11111110, %11111110, %00000000
        ASSERT $ <= $8000, the program is longer than the cartridge
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
